import{_ as d,o as r,c as a,a3 as e}from"./chunks/framework.BWzgKoSO.js";const c=JSON.parse('{"title":"附 A　食物交换表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/a-food-table.md","filePath":"appendix/a-food-table.md","lastUpdated":1793337833000}'),o={name:"appendix/a-food-table.md"};function h(n,t,l,i,p,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="附-a-食物交换表" tabindex="-1">附 A　食物交换表 <a class="header-anchor" href="#附-a-食物交换表" aria-label="Permalink to &quot;附 A　食物交换表&quot;">​</a></h1><p>不用背热量表，也不用天天称重。下面这一套是个现成的尺子。</p><h2 id="一把尺子-一份-90-千卡" tabindex="-1">一把尺子：一份 90 千卡 <a class="header-anchor" href="#一把尺子-一份-90-千卡" aria-label="Permalink to &quot;一把尺子：一份 90 千卡&quot;">​</a></h2><p>《成人肥胖食养指南（2024 年版）》附录 2 把整套表收了进去，表格的出处是中国营养学会的《食物交换份》团体标准（T/CNSS 020—2023）〔G1，A〕。</p><p>规则只有一条：<strong>同类的食物里，一份和一份可以互换，热量都是 90 千卡。</strong></p><p>七十克米饭、三十克面食、五百克蔬菜、一个鸡蛋、一盒脱脂牛奶，在热量上大致是一回事。这条规则的意义是：你不需要记住每一种食物的热量，只要记住一份等于多少，以及同类之间可以换。</p><p>一天能吃几份？你的目标热量除以 90。1800 千卡就是 20 份。</p><p>下面的克数都是可食部——去掉骨头、皮、籽以后能吃的净重。</p><h2 id="谷薯杂豆类" tabindex="-1">谷薯杂豆类 <a class="header-anchor" href="#谷薯杂豆类" aria-label="Permalink to &quot;谷薯杂豆类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>一份的克数</th><th>家常大概是多少</th></tr></thead><tbody><tr><td>谷物（大米、面粉、玉米面，干的生的）</td><td>25</td><td>两瓷勺米</td></tr><tr><td>面制品（馒头、花卷、大饼、湿面条、面包）</td><td>35</td><td>半个小馒头</td></tr><tr><td>米饭（粳米、籼米饭，熟的）</td><td>75</td><td>半拳头</td></tr><tr><td>全谷物（糙米、燕麦、小米、荞麦）</td><td>25</td><td>两瓷勺</td></tr><tr><td>杂豆（绿豆、红豆、蚕豆、豌豆）</td><td>25</td><td>两瓷勺</td></tr><tr><td>粉条、粉丝、淀粉</td><td>25</td><td>一小把干粉条</td></tr><tr><td>糕点和油炸类（蛋糕、油条、油饼）</td><td>20</td><td>半根油条</td></tr><tr><td>薯芋类（土豆、红薯、山药、芋头）</td><td>100</td><td>半个中等土豆</td></tr></tbody></table><p>薯芋类那一行特别值得记：一百克土豆和二十五克大米热量一样。所以土豆不是菜，它跟米饭站在同一个格子里。</p><h2 id="蔬菜类" tabindex="-1">蔬菜类 <a class="header-anchor" href="#蔬菜类" aria-label="Permalink to &quot;蔬菜类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>一份的克数</th><th>举例</th></tr></thead><tbody><tr><td>蔬菜（综合，分不清哪种时用它）</td><td>250</td><td>一大盘</td></tr><tr><td>深色嫩茎叶花菜</td><td>300</td><td>菠菜、油菜、芹菜、苋菜</td></tr><tr><td>浅色嫩茎叶花菜</td><td>330</td><td>大白菜、娃娃菜、菜花、竹笋</td></tr><tr><td>茄果类</td><td>375</td><td>黄瓜、西红柿、茄子、西葫芦、南瓜</td></tr><tr><td>根茎类（不含土豆芋头）</td><td>300</td><td>白萝卜、胡萝卜、水萝卜</td></tr><tr><td>鲜蘑菇</td><td>275</td><td>香菇、平菇、金针菇</td></tr><tr><td>干蘑菇</td><td>30</td><td>香菇干、木耳、茶树菇</td></tr><tr><td>鲜豆类</td><td>250</td><td>豇豆、扁豆、四季豆、刀豆</td></tr></tbody></table><p>蔬菜的份量门槛低得让人放心：一大盘绿叶菜才一份。这也是全书里唯一可以放心“多吃”的一类。</p><h2 id="水果类" tabindex="-1">水果类 <a class="header-anchor" href="#水果类" aria-label="Permalink to &quot;水果类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>一份的克数</th><th>举例</th></tr></thead><tbody><tr><td>水果（综合）</td><td>150</td><td>一个中等苹果</td></tr><tr><td>柑橘类</td><td>200</td><td>两个橘子</td></tr><tr><td>仁果核果瓜果（苹果、梨、桃、西瓜、哈密瓜）</td><td>175</td><td>一个中等苹果</td></tr><tr><td>浆果类（葡萄、草莓、猕猴桃、柿子）</td><td>150</td><td>一小串葡萄</td></tr><tr><td>枣和热带水果（鲜枣、芒果、荔枝、香蕉、榴莲）</td><td>75</td><td>半根香蕉</td></tr><tr><td>果干</td><td>25</td><td>五六颗葡萄干</td></tr></tbody></table><p>最后两行是对照最强烈的：一百五十克草莓和七十五克香蕉热量一样。香蕉、荔枝、榴莲、鲜枣不是不能吃，是“一份”的分量小得多。</p><h2 id="肉蛋水产类" tabindex="-1">肉蛋水产类 <a class="header-anchor" href="#肉蛋水产类" aria-label="Permalink to &quot;肉蛋水产类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>一份的克数</th><th>举例</th></tr></thead><tbody><tr><td>畜禽肉（综合）</td><td>50</td><td>一掌心</td></tr><tr><td>畜肉，脂肪 ≤5%</td><td>80</td><td>牛里脊、羊里脊、纯瘦肉</td></tr><tr><td>畜肉，脂肪 6%～15%</td><td>60</td><td>猪里脊、羊胸脯</td></tr><tr><td>畜肉，脂肪 16%～35%</td><td>30</td><td>前臀尖、猪大排、硬五花（两三块）</td></tr><tr><td>畜肉，脂肪 ≥85%</td><td>10</td><td>肥肉、板油</td></tr><tr><td>禽肉（鸡鸭鹅）</td><td>50</td><td>一个去皮鸡腿的一半</td></tr><tr><td>蛋类</td><td>60</td><td>一个鸡蛋</td></tr><tr><td>水产（综合）</td><td>90</td><td>一整块鱼柳</td></tr><tr><td>鱼类（鲤鱼、草鱼、鲈鱼、带鱼）</td><td>75</td><td>掌心大的一块鱼柳</td></tr><tr><td>虾蟹贝类</td><td>115</td><td>七八只中等虾</td></tr></tbody></table><p>这一张表最能说明问题：同样是“一份”，瘦里脊能吃到八十克，五花肉只有三十克，肥肉十克。脂肪每克九千卡，把肉的“性价比”压得只剩零头。</p><h2 id="坚果类" tabindex="-1">坚果类 <a class="header-anchor" href="#坚果类" aria-label="Permalink to &quot;坚果类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>一份的克数</th><th>举例</th></tr></thead><tbody><tr><td>坚果（综合）</td><td>20</td><td>一小把</td></tr><tr><td>淀粉类坚果（板栗、白果、莲子）</td><td>25</td><td>三四颗板栗</td></tr><tr><td>高脂类坚果（核桃、花生、瓜子、杏仁、松子、芝麻）</td><td>15</td><td>两三个核桃</td></tr><tr><td>中脂类坚果（腰果、鲜核桃、白芝麻）</td><td>20</td><td>十几颗腰果</td></tr></tbody></table><p>十五克高脂坚果就是三四个核桃，很多人一坐下一袋就没了。这是全书里最容易吃超的一项。</p><h2 id="大豆、乳及其制品" tabindex="-1">大豆、乳及其制品 <a class="header-anchor" href="#大豆、乳及其制品" aria-label="Permalink to &quot;大豆、乳及其制品&quot;">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th>一份的克数</th><th>举例</th></tr></thead><tbody><tr><td>大豆（黄豆、黑豆、青豆）</td><td>20</td><td>一小把干豆</td></tr><tr><td>豆粉</td><td>20</td><td>两瓷勺</td></tr><tr><td>北豆腐</td><td>90</td><td>四分之一块</td></tr><tr><td>南豆腐</td><td>150</td><td>一盒嫩豆腐的大半</td></tr><tr><td>豆皮、豆干、素鸡</td><td>50</td><td>一片半豆干</td></tr><tr><td>豆浆</td><td>330</td><td>一大杯</td></tr><tr><td>全脂牛奶</td><td>150</td><td>大半盒</td></tr><tr><td>脱脂牛奶</td><td>265</td><td>一盒多</td></tr><tr><td>发酵乳（全脂酸奶）</td><td>100</td><td>一小杯</td></tr><tr><td>乳酪</td><td>25</td><td>一片</td></tr><tr><td>乳粉</td><td>20</td><td>两瓷勺</td></tr></tbody></table><p>脱脂牛奶能喝到二百六十五克，全脂只有一百五十克。差别就在那一层脂肪上——这也是为什么减重期指南推荐低脂或脱脂奶。</p><h2 id="一天-20-份怎么排" tabindex="-1">一天 20 份怎么排 <a class="header-anchor" href="#一天-20-份怎么排" aria-label="Permalink to &quot;一天 20 份怎么排&quot;">​</a></h2><p>拿 1800 千卡举例，一天二十份，可以这么分：</p><ul><li>谷薯杂豆 <strong>9 份</strong>（810 千卡）</li><li>蔬菜 <strong>2 份</strong>（180 千卡）</li><li>水果 <strong>2 份</strong>（180 千卡）</li><li>肉蛋水产 <strong>4 份</strong>（360 千卡）</li><li>大豆乳 <strong>2 份</strong>（180 千卡）</li><li>坚果 <strong>1 份</strong>（90 千卡）</li></ul><p>加起来正好 20 份、1800 千卡。按表里每份的蛋白质算下来，这份排法大约八十克蛋白，一个六十公斤的人对应 1.3 克/公斤，落在 3.2 那一节的范围里。</p><p>这个分配不是标准答案，是一把可以调的尺子。爱吃肉的把肉加一份、谷薯减一份，热量不变，蛋白更高。这就是“交换”的意思。</p><h2 id="不在交换份里的几样" tabindex="-1">不在交换份里的几样 <a class="header-anchor" href="#不在交换份里的几样" aria-label="Permalink to &quot;不在交换份里的几样&quot;">​</a></h2><p><strong>油。</strong> 一克九千卡，十克一瓷勺就是九十千卡——一勺油正好也是一份。一天 25～30 克的烹调油上限，就是三份。这个量很多人炒两个菜就超了。</p><p><strong>盐。</strong> 不产生热量，但一克盐约含 0.39 克钠，一天上限 5 克。</p><p><strong>酒。</strong> 一克七千卡，跟糖差不多。二两五十度的白酒约三百千卡，等于三份多，而且这些份不占肚子。</p><p><strong>饮料。</strong> 一罐可乐约一百四十千卡，一份半。无糖的按国标是每百毫升不超过 17 千焦，热量可以按零算，但别把“无糖”当“可以多喝”。</p><h2 id="外卖和餐馆怎么估" tabindex="-1">外卖和餐馆怎么估 <a class="header-anchor" href="#外卖和餐馆怎么估" aria-label="Permalink to &quot;外卖和餐馆怎么估&quot;">​</a></h2><p>中餐的份量没有标准，所以别追精确到个位，抓量级就够了。</p><p>三个抓手：</p><p><strong>一，先看主食。</strong> 一碗米饭按二百克算，差不多两份半；一碗面条的干面通常八十到一百克，三到四份。主食的份数先定住，这一顿就定了大半。</p><p><strong>二，再看油。</strong> 餐馆的菜，油是家里的一倍到两倍。同样一份青菜，家里炒是一份，馆子里炒可能要加两三勺油。点菜时优先清蒸、白灼、炖，这一条比算热量有用。</p><p><strong>三，最后数肉。</strong> 一掌心算一份。红烧肉、糖醋排骨这类，肉只有几块，油和糖却在里面，就要在肉的基础上再加一两份。</p><p>这三步不需要秤，也不需要查表，坐下就能做。误差肯定有，但方向不会错——而减重最需要的恰恰是方向，不是小数点。</p><h2 id="这张表的边界" tabindex="-1">这张表的边界 <a class="header-anchor" href="#这张表的边界" aria-label="Permalink to &quot;这张表的边界&quot;">​</a></h2><p>表是官方文件里的，克数是准的；但“家常大概是多少”那一列是我按常见的碗、拳头、掌心折算的，只能当参考，不能当秤用。</p><p>真正要称的时候还是称：连续称一两周，你对自己那只碗、那个拳头的体积就有数了，之后不称也准。</p>',46)])])}const u=d(o,[["render",h]]);export{c as __pageData,u as default};
